import java.util.Random;
import java.util.Arrays;

public class RandomArrayGenerator {

    /**
     * Generate array of random integers
     * @param size length of array
     * @param min minimum value (inclusive)
     * @param max maximum value (inclusive)
     * @return array of random integers
     */
    public static int[] generateRandomIntegers(int size, int min, int max) {
        Random random = new Random();
        int[] array = new int[size];

        for (int i = 0; i < size; i++) {
            array[i] = random.nextInt(max - min + 1) + min;
        }

        return array;
    }

    /**
     * Generate array of random doubles
     * @param size length of array
     * @param min minimum value
     * @param max maximum value
     * @return array of random doubles
     */
    public static double[] generateRandomDoubles(int size, double min, double max) {
        Random random = new Random();
        double[] array = new double[size];

        for (int i = 0; i < size; i++) {
            array[i] = min + (max - min) * random.nextDouble();
        }

        return array;
    }

    public static void main(String[] args) {
        // Generate random integers
        int[] intArray = generateRandomIntegers(10, 1, 100);
        System.out.println("Random integers: " + Arrays.toString(intArray));

        // Generate random doubles
        double[] doubleArray = generateRandomDoubles(10, 0.0, 10.0);
