Here's a complete implementation of a Binary Search Tree (BST) in Python with all essential operations:

## Node Class

```python
class TreeNode:
    def __init__(self, val=0):
        self.val = val
        self.left = None
        self.right = None
```

## Binary Search Tree Implementation

```python
class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, val):
        """Insert a value into the BST"""
        if self.root is None:
            self.root = TreeNode(val)
        else:
            self._insert_recursive(self.root, val)

    def _insert_recursive(self, node, val):
        """Helper method for recursive insertion"""
        if val < node.val:
            if node.left is None:
                node.left = TreeNode(val)
            else:
                self._insert_recursive(node.left, val)
        elif val > node.val:
            if node.right is None:
                node.right = TreeNode(val)
            else:
                self._insert_recursive(node.right, val)
        # If val == node.val, we don't insert duplicates (optional)

    def search(self, val):
        """Search for a value in the BST"""
        return self._search_recursive(self.root, val)

    def _search_recursive(self, node, val):
        """Helper method for recursive search"""
        if node is None or node.val == val:
            return node is not None

        if val < node.val:
            return self._search_recursive(node.left, val)
        else:
            return self._search_recursive(node.right, val)

    def delete(self, val):
        """Delete a value from the BST"""
        self.root = self._delete_recursive(self.root, val)

    def _delete_recursive(self, node, val):
        """Helper method for recursive deletion"""
        if node is None:
            return node

        if val < node.val:
            node.left = self._delete_recursive(node.left, val)
        elif val > node.val:
            node.right = self._delete_recursive(node.right, val)
        else:
            # Node to be deleted found
            # Case 1: Node has no children (leaf node)
            if node.left is None and node.right is None:
                return None

            # Case 2: Node has one child
            elif node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            # Case 3: Node has two children
            else:
                # Find inorder successor (smallest value in right subtree)
                successor = self._find_min(node.right)
                node.val = successor.val
                node.right = self._delete_recursive(node.right, successor.val)

        return node

    def _find_min(self, node):
        """Find the node with minimum value in subtree"""
        while node.left is not None:
            node = node.left
        return node

    def find_min(self):
        """Find minimum value in the BST"""
        if self.root is None:
            return None
        current = self.root
        while current.left is not None:
            current = current.left
        return current.val

    def find_max(self):
        """Find maximum value in the BST"""
        if self.root is None:
            return None
        current = self.root
        while current.right is not None:
            current = current.right
        return current.val

    def inorder_traversal(self):
        """Return inorder traversal (sorted order)"""
        result = []
        self._inorder_recursive(self.root, result)
        return result

    def _inorder_recursive(self, node, result):
        """Helper method for inorder traversal"""
        if node:
            self._inorder_recursive(node.left, result)
            result.append(node.val)
            self._inorder_recursive(node.right, result)

    def preorder_traversal(self):
        """Return preorder traversal"""
        result = []
        self._preorder_recursive(self.root, result)
        return result

    def _preorder_recursive(self, node, result):
        """Helper method for preorder traversal"""
        if node:
            result.append(node.val)
            self._preorder_recursive(node.left, result)
            self._preorder_recursive(node.right, result)

    def postorder_traversal(self):
        """Return postorder traversal"""
        result = []
        self._postorder_recursive(self.root, result)
        return result

    def _postorder_recursive(self, node, result):
        """Helper method for postorder traversal"""
        if node:
            self._postorder_recursive(node.left, result)
            self._postorder_recursive(node.right, result)
            result.append(node.val)

    def height(self):
        """Calculate the height of the BST"""
        return self._height_recursive(self.root)

    def _height_recursive(self, node):
        """Helper method for height calculation"""
        if node is None:
            return -1

        left_height = self._height_recursive(node.left)
        right_height = self._height_recursive(node.right)

        return max(left_height, right_height) + 1

    def size(self):
        """Count the number of nodes in the BST"""
        return self._size_recursive(self.root)

    def _size_recursive(self, node):
        """Helper method for size calculation"""
        if node is None:
            return 0
        return 1 + self._size_recursive(node.left) + self._size_recursive(node.right)

    def is_empty(self):
        """Check if the BST is empty"""
        return self.root is None
```

## Example Usage

```python
# Create a BST and test the operations
bst = BinarySearchTree()

# Insert values
values = [50, 30, 70, 20, 40, 60, 80]
for val in values:
    bst.insert(val)

print("Inorder traversal (sorted):", bst.inorder_traversal())
print("Preorder traversal:", bst.preorder_traversal())
print("Postorder traversal:", bst.postorder_traversal())

print("Search for 40:", bst.search(40))  # True
print("Search for 25:", bst.search(25))  # False

print("Minimum value:", bst.find_min())  # 20
print("Maximum value:", bst.find_max())  # 80
print("Height:", bst.height())           # 2
print("Size:", bst.size())               # 7

# Delete a node
bst.delete(30)
print("After deleting 30:", bst.inorder_traversal())
```

## Key Features

1. **Insert**: O(log n) average, O(n) worst case
2. **Search**: O(log n) average, O(n) worst case
3. **Delete**: O(log n) average, O(n) worst case
4. **Traversals**: O(n) for all traversal methods
5. **Space Complexity**: O(n) for storing n nodes

## Time Complexities

- **Best/Average Case**: O(log n) - when the tree is balanced
- **Worst Case**: O(n) - when the tree becomes skewed (like a linked list)

This implementation provides a robust foundation for a binary search tree with all standard operations. For production use, you might want to consider self-balancing BSTs (like AVL trees or Red-Black trees) to maintain O(log n) operations in all cases.

Find the errors in the following code and fix them.
if (x > y) {
if (x == y)
  y = 0;
else
  x = 0;
}

The code has a **logical error** in the nested `if` statement. Let's analyze it:

```c
if (x > y) {
    if (x == y)
        y = 0;
    else
        x = 0;
}
```

### Problem:
The nested condition `if (x == y)` is **inside** the outer `if (x > y)` block. However, if `x > y` is true, then `x == y` **cannot** be true — these two conditions are **mutually exclusive**.

So, the inner `if (x == y)` will **never** evaluate to true when `x > y` is true. This makes the condition logically unreachable or flawed — likely a programming mistake.

### Possible Intents:
1. The programmer might have meant to check `x > y`, `x == y`, and `x < y` cases.
2. Or perhaps they meant `if (x >= y)` instead of `x > y`.

But given the structure, it's more likely the intended logic was to handle three cases:

- If `x > y`, do something
- Else if `x == y`, do something else
- Else (`x < y`), another thing

Or maybe the inner condition was meant to be something else, like `x > some_value`.

However, another **real bug** (beyond logic) arises due to **dangling else** ambiguity, although in C/C++ the `else` binds to the nearest `if`. So syntactically, the `else` belongs to the inner `if (x == y)`. But since that inner `if` is inside a block, the code is:

```c
if (x > y) {
    if (x == y)
        y = 0;
    else
        x = 0;
}
```

Means:
- If `x > y`:
  - If `x == y`, set `y = 0` (impossible)
  - Else (i.e., `x != y`, but we already know `x > y`), set `x = 0`

So whenever `x > y`, since `x == y` is false, the `else` block runs and sets `x = 0`.

But that might **not** be the intention.

---

### Likely Fix:
Perhaps the programmer meant to write:

```c
if (x > y) {
    // do something
    x = 0;
} else if (x == y) {
    y = 0;
} else {
    // x < y
    // possibly another action
}
```

Or if the only intent was to handle `x > y` and `x == y` separately:

### Corrected version assuming intent was to compare three cases:

```c
if (x > y) {
    x = 0;
} else if (x == y) {
    y = 0;
}
// else x < y, handle if needed
```

Or, if the original structure was meant to be simpler, maybe the inner condition was a typo and should have been something else (e.g., `x > z`), but without context, the most plausible **logical fix** is to restructure the conditions meaningfully.

---

### ✅ Fixed Version (Assuming Logical Intent):
```c
if (x > y) {
    x = 0;
} else if (x == y) {
    y = 0;
}
```

This properly handles:
- `x > y` → `x = 0`
- `x == y` → `y = 0`
- (and `x < y` does nothing, unless more logic is added)

### Summary of Errors:
1. **Logical contradiction**: `x > y` and `x == y` cannot both be true.
2. **Dead code**: `if (x == y)` inside `if (x > y)` will never execute.
3. **Misplaced else**: The `else` applies to inner `if`, leading to unintended behavior.

✅ Fixed by restructuring the conditions.

Here are several implementations of a leap year checker function in different programming languages:

## Python

```python
def is_leap_year(year):
    """
    Check if a given year is a leap year.

    A year is a leap year if:
    - It is divisible by 4, AND
    - If it is divisible by 100, it must also be divisible by 400

    Args:
        year (int): The year to check

    Returns:
        bool: True if the year is a leap year, False otherwise
    """
    if year % 400 == 0:
