public class LeapYearChecker {

    /**
     * Check if a given year is a leap year.
     * 
     * A year is a leap year if:
     * - It is divisible by 4, AND
     * - If it is divisible by 100, it must also be divisible by 400
     * 
     * @param year The year to check
     * @return true if the year is a leap year, false otherwise
     */
    public static boolean isLeapYear(int year) {
        if (year % 400 == 0) {
            return true;
        } else if (year % 100 == 0) {
            return false;
        } else if (year % 4 == 0) {
            return true;
        } else {
            return false;
        }
    }

    // Alternative one-liner version
    public static boolean isLeapYearSimple(int year) {
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }

    // Test the function
    public static void main(String[] args) {
        int[] testYears = {2000, 2004, 1900, 2001, 2024, 2100};

        for (int year : testYears) {
            boolean result = isLeapYear(year);
            System.out.println(year + " is " + (result ? "a leap year" : "not a leap year"));
        }
    }
}
