Here's a C++ implementation of Breadth-First Search (BFS) for a graph:

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

class Graph {
private:
    int numVertices;
    vector<vector<int>> adjList;

public:
    // Constructor
    Graph(int vertices) {
        numVertices = vertices;
        adjList.resize(vertices);
    }

    // Add edge to the graph
    void addEdge(int src, int dest) {
        adjList[src].push_back(dest);
        adjList[dest].push_back(src); // For undirected graph
        // Remove the second line if you want a directed graph
    }

    // BFS traversal from a given starting vertex
    void BFS(int startVertex) {
        vector<bool> visited(numVertices, false);
        queue<int> q;

        // Mark the starting vertex as visited and enqueue it
        visited[startVertex] = true;
        q.push(startVertex);

        cout << "BFS traversal starting from vertex " << startVertex << ": ";

        while (!q.empty()) {
            // Dequeue a vertex from queue and print it
            int currentVertex = q.front();
            q.pop();
            cout << currentVertex << " ";

            // Get all adjacent vertices of the dequeued vertex
            // If an adjacent vertex has not been visited, mark it as visited and enqueue it
            for (int adjacentVertex : adjList[currentVertex]) {
                if (!visited[adjacentVertex]) {
                    visited[adjacentVertex] = true;
                    q.push(adjacentVertex);
                }
            }
        }
        cout << endl;
    }

    // BFS to find shortest path from start to target
    int shortestPath(int startVertex, int targetVertex) {
        if (startVertex == targetVertex) return 0;

        vector<bool> visited(numVertices, false);
        queue<pair<int, int>> q; // {vertex, distance}

        visited[startVertex] = true;
        q.push({startVertex, 0});

        while (!q.empty()) {
            auto current = q.front();
            q.pop();
            int currentVertex = current.first;
            int distance = current.second;

            // Check all adjacent vertices
            for (int adjacentVertex : adjList[currentVertex]) {
                if (adjacentVertex == targetVertex) {
                    return distance + 1;
                }

                if (!visited[adjacentVertex]) {
                    visited[adjacentVertex] = true;
                    q.push({adjacentVertex, distance + 1});
                }
            }
        }

        return -1; // Target not reachable
    }

    // Print the adjacency list
    void printGraph() {
        cout << "Adjacency List:" << endl;
        for (int i = 0; i < numVertices; i++) {
            cout << i << " -> ";
            for (int j : adjList[i]) {
                cout << j << " ";
            }
            cout << endl;
        }
    }
};

// Example usage
int main() {
    // Create a graph with 6 vertices (0 to 5)
    Graph graph(6);

    // Add edges
    graph.addEdge(0, 1);
    graph.addEdge(0, 2);
    graph.addEdge(1, 3);
    graph.addEdge(1, 4);
    graph.addEdge(2, 4);
    graph.addEdge(3, 5);
    graph.addEdge(4, 5);

    // Print the graph
    graph.printGraph();
    cout << endl;

    // Perform BFS from vertex 0
    graph.BFS(0);

    // Find shortest path from 0 to 5
    int pathLength = graph.shortestPath(0, 5);
    cout << "Shortest path from 0 to 5: " << pathLength << " edges" << endl;

    return 0;
}
```

**Key features of this BFS implementation:**

1. **Graph Representation**: Uses adjacency list with a vector of vectors
2. **Main BFS Function**: Traverses the graph level by level using a queue
3. **Visited Tracking**: Uses a boolean vector to avoid revisiting vertices
4. **Shortest Path**: Includes a function to find the shortest path between two vertices
5. **Undirected Graph**: The `addEdge` function adds edges in both directions

**Time Complexity**: O(V + E) where V is the number of vertices and E is the number of edges
**Space Complexity**: O(V) for the visited array and queue

**Output for the example:**
```
Adjacency List:
0 -> 1 2 
1 -> 0 3 4 
2 -> 0 4 
3 -> 1 5 
4 -> 1 2 5 
5 -> 3 4 

BFS traversal starting from vertex 0: 0 1 2 3 4 5 
Shortest path from 0 to 5: 3 edges
```

You can modify this implementation for directed graphs by removing one of the `push_back` statements in the `addEdge` method, or adapt it for weighted graphs by using a different data structure.

