Here's a C++ function to calculate the area of a triangle using different methods:

```cpp
#include <iostream>
#include <cmath>

class Triangle {
public:
    // Method 1: Calculate area using base and height
    static double areaWithBaseHeight(double base, double height) {
        if (base <= 0 || height <= 0) {
            std::cerr << "Error: Base and height must be positive values." << std::endl;
            return -1.0;
        }
        return 0.5 * base * height;
    }

    // Method 2: Calculate area using three sides (Heron's formula)
    static double areaWithSides(double a, double b, double c) {
        // Check if sides are positive
        if (a <= 0 || b <= 0 || c <= 0) {
            std::cerr << "Error: All sides must be positive values." << std::endl;
            return -1.0;
        }

        // Check triangle inequality
        if (a + b <= c || a + c <= b || b + c <= a) {
            std::cerr << "Error: Invalid triangle - sides don't satisfy triangle inequality." << std::endl;
            return -1.0;
        }

        // Heron's formula
        double s = (a + b + c) / 2.0;  // semi-perimeter
        double area = sqrt(s * (s - a) * (s - b) * (s - c));

        return area;
    }

    // Method 3: Calculate area using coordinates of vertices
    static double areaWithCoordinates(double x1, double y1, double x2, double y2, double x3, double y3) {
        // Using the cross product formula
        return 0.5 * abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));
    }
};

// Example usage and demonstration
int main() {
    std::cout << "Triangle Area Calculator" << std::endl;
    std::cout << "========================" << std::endl;

    // Example 1: Using base and height
    double base = 10.0, height = 8.0;
    double area1 = Triangle::areaWithBaseHeight(base, height);
    std::cout << "Area (base=" << base << ", height=" << height << "): " << area1 << std::endl;

    // Example 2: Using three sides
    double side1 = 3.0, side2 = 4.0, side3 = 5.0;
    double area2 = Triangle::areaWithSides(side1, side2, side3);
    std::cout << "Area (sides " << side1 << ", " << side2 << ", " << side3 << "): " << area2 << std::endl;

    // Example 3: Using coordinates
    double area3 = Triangle::areaWithCoordinates(0, 0, 4, 0, 0, 3);
    std::cout << "Area (coordinates): " << area3 << std::endl;

    // Example of error handling
    std::cout << "\nError handling examples:" << std::endl;
    Triangle::areaWithBaseHeight(-5, 10);  // Invalid base
    Triangle::areaWithSides(1, 1, 5);      // Invalid triangle (violates triangle inequality)

    return 0;
}
```

**Key Features:**

1. **Multiple Methods**: Provides three different ways to calculate triangle area
2. **Error Handling**: Validates inputs and checks triangle validity
3. **Static Methods**: Easy to use without creating objects
4. **Well-documented**: Clear function names and comments

**The Three Methods:**

1. **Base and Height**: `Area = ½ × base × height`
2. **Three Sides (Heron's Formula)**: `Area = √[s(s-a)(s-b)(s-c)]` where `s = (a+b+c)/2`
3. **Vertex Coordinates**: Uses the determinant formula for area calculation

**Sample Output:**
```
Triangle Area Calculator
========================
Area (base=10, height=8): 40
Area (sides 3, 4, 5): 6
Area (coordinates): 6

Error handling examples:
Error: Base and height must be positive values.
Error: Invalid triangle - sides don't satisfy triangle inequality.
```

This implementation is robust, handles edge cases, and provides multiple ways to calculate triangle area depending on the available information.

