Here's a JavaScript implementation that calculates a prefix sum array and provides a function to get the sum of elements from index `l` to `r`:

```javascript
class PrefixSum {
    constructor(arr) {
        this.arr = arr;
        this.prefixSum = this.calculatePrefixSum();
    }

    // Calculate prefix sum array
    calculatePrefixSum() {
        if (this.arr.length === 0) return [];

        const prefix = new Array(this.arr.length);
        prefix[0] = this.arr[0];

        for (let i = 1; i < this.arr.length; i++) {
            prefix[i] = prefix[i - 1] + this.arr[i];
        }

        return prefix;
    }

    // Return sum from index l to r (inclusive)
    rangeSum(l, r) {
        // Validate indices
        if (l < 0 || r >= this.arr.length || l > r) {
            throw new Error('Invalid indices: l and r must be within array bounds and l <= r');
        }

        // If l is 0, return prefixSum[r]
        // Otherwise, return prefixSum[r] - prefixSum[l-1]
        return l === 0 ? this.prefixSum[r] : this.prefixSum[r] - this.prefixSum[l - 1];
    }
}

// Alternative: Simple function approach
function createPrefixSum(arr) {
    // Calculate prefix sum array
    const prefixSum = [];
    if (arr.length === 0) return prefixSum;

    prefixSum[0] = arr[0];
    for (let i = 1; i < arr.length; i++) {
        prefixSum[i] = prefixSum[i - 1] + arr[i];
    }

    // Return function to get range sum
    return function rangeSum(l, r) {
        if (l < 0 || r >= arr.length || l > r) {
            throw new Error('Invalid indices');
        }

        return l === 0 ? prefixSum[r] : prefixSum[r] - prefixSum[l - 1];
    };
}

// Example usage:
console.log('=== Using Class Approach ===');
const nums = [1, 3, 4, 8, 6, 1, 4, 2];
const prefixSum = new PrefixSum(nums);

console.log('Original array:', nums);
console.log('Prefix sum:', prefixSum.prefixSum);

console.log('Sum from 0 to 3:', prefixSum.rangeSum(0, 3)); // 1+3+4+8 = 16
console.log('Sum from 2 to 5:', prefixSum.rangeSum(2, 5)); // 4+8+6+1 = 19
console.log('Sum from 4 to 4:', prefixSum.rangeSum(4, 4)); // 6

console.log('\n=== Using Function Approach ===');
const getRangeSum = createPrefixSum(nums);

console.log('Sum from 1 to 4:', getRangeSum(1, 4)); // 3+4+8+6 = 21
console.log('Sum from 3 to 7:', getRangeSum(3, 7)); // 8+6+1+4+2 = 21
```

**How it works:**

1. **Prefix Sum Calculation**: 
   - `prefixSum[i] = sum of elements from index 0 to i`
   - Built in O(n) time

2. **Range Sum Query**:
   - For range `[l, r]`: `sum = prefixSum[r] - prefixSum[l-1]`
   - If `l = 0`, then `sum = prefixSum[r]`
   - Each query runs in O(1) time

**Time Complexity:**
- Preprocessing: O(n)
- Each query: O(1)
- Total for q queries: O(n + q)

**Space Complexity:** O(n) for the prefix sum array

This approach is very efficient when you need to answer multiple range sum queries on the same array.

