                'timestamp': datetime.utcnow().isoformat() + 'Z'
            }), 404

        return jsonify({
            'success': True,
            'data': {
                'id': latest_book.id,
                'title': latest_book.title,
                'author': latest_book.author,
                'isbn': latest_book.isbn,
                'publicationDate': latest_book.publication_date.isoformat(),
                'publisher': latest_book.publisher,
                'genre': latest_book.genre,
                'pages': latest_book.pages,
                'language': latest_book.language,
                'description': latest_book.description,
                'coverImage': latest_book.cover_image,
                'price': float(latest_book.price) if latest_book.price else None,
                'currency': 'USD',  # This could be dynamic based on user location
                'rating': latest_book.rating,
                'reviewsCount': latest_book.reviews_count,
                'availability': latest_book.availability
            },
            'timestamp': datetime.utcnow().isoformat() + 'Z'
        }), 200

    except Exception as e:
        print(f"Error fetching latest book: {e}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'timestamp': datetime.utcnow().isoformat() + 'Z'
        }), 500
```

### Query Parameters (Optional)

- `fields=[title,author,price]` - Limit returned fields
- `includeReviews=true` - Include review details
- `currency=EUR` - Convert price to specified currency

